{-| @Backend.Runtime.Host.Audio — AudioToolbox playback and stream outcomes. -}
module Pudu.Backend.Runtime.Host.Audio (hostAudioParts) where

import Data.Text (Text)
import Pudu.Backend.Toolchain.HostSources (audioSourceMarker)

hostAudioParts :: [(Text, [Text], [Text])]
hostAudioParts =
  [ ("host_audio", ["host_optional", "host_fail", "host_done", "memory_failure", "kernel_signed"],
      [ audioSourceMarker
      , "#if defined(__APPLE__)"
      , "#include \"pudu_audio.h\""
      , "#include \"pudu_audio_stream.h\""
      , "#endif"
      ])
  , ("host_audio_stream", ["host_audio"],
      [ "#if defined(__APPLE__)"
      , "typedef struct pudu_stream_entry {"
      , "  int64_t token;"
      , "  pudu_audio_stream *stream;"
      , "  struct pudu_stream_entry *next;"
      , "} pudu_stream_entry;"
      , "static pudu_stream_entry *pudu_streams = NULL;"
      , "PUDU_OPTIONAL static int64_t pudu_stream_next = 1;"
      , "PUDU_OPTIONAL static void pudu_stream_teardown(void) {"
      , "  while (pudu_streams != NULL) {"
      , "    pudu_stream_entry *entry = pudu_streams;"
      , "    pudu_streams = entry->next;"
      , "    (void)pudu_audio_stream_close(entry->stream, 0, 1);"
      , "    free(entry);"
      , "  }"
      , "}"
      , "PUDU_OPTIONAL static pudu_stream_entry **pudu_stream_find(pudu_int token) {"
      , "  pudu_stream_entry **entry = &pudu_streams;"
      , "  while (*entry != NULL && (*entry)->token != pudu_kernel_signed(token.bits)) entry = &(*entry)->next;"
      , "  if (*entry == NULL) pudu_host_fail(\"audio stream is closed or unknown\");"
      , "  return entry;"
      , "}"
      , "PUDU_OPTIONAL static int pudu_stream_problem(int status) {"
      , "  static const char *const words[] = {"
      , "    \"audio stream failed in the platform adapter\","
      , "    \"audio stream received an invalid argument\","
      , "    \"audio stream operation deadline exceeded\","
      , "    \"audio output stream could not be created\","
      , "    \"audio output stream buffers could not be allocated\","
      , "    \"audio output stream buffer could not be enqueued\","
      , "    \"audio output stream control failed\","
      , "    \"audio output stream could not be released cleanly\","
      , "    \"audio output stream timeline is unavailable\""
      , "  };"
      , "  if (status == 0) pudu_host_done(0);"
      , "  else pudu_host_fail(words[status >= -8 && status <= -1 ? -status : 0]);"
      , "  return 0;"
      , "}"
      , "#endif"
      ])
  , ("host_audio_stream_array", ["host_audio_stream", "array", "kernel_int"],
      [ "#if defined(__APPLE__)"
      , "PUDU_OPTIONAL static pudu_box *pudu_stream_answer(const uint64_t *values, size_t count) {"
      , "  pudu_box *array = pudu_array_new(count);"
      , "  for (size_t i = 0; i < count; ++i)"
      , "    array->fields[0].items->cells[i].integer = pudu_kernel_int(pudu_kernel_signed(values[i]));"
      , "  pudu_array_length(array) = count;"
      , "  pudu_host_done(0);"
      , "  return array;"
      , "}"
      , "#endif"
      ])
  , ("host_audio_device_play", ["host_audio", "kernel_int", "host_signal_requested"],
      [ "static pudu_int pudu_host_audio_device_play(pudu_int rate, pudu_int channels, pudu_box * bytes, pudu_int frames, pudu_int buffers, pudu_int timeout) {"
      , "  int64_t rate_value = pudu_kernel_signed(rate.bits);"
      , "  int64_t channels_value = pudu_kernel_signed(channels.bits);"
      , "  int64_t frames_value = pudu_kernel_signed(frames.bits);"
      , "  int64_t buffers_value = pudu_kernel_signed(buffers.bits);"
      , "  int64_t timeout_value = pudu_kernel_signed(timeout.bits);"
      , "  pudu_text pcm = bytes->fields[0].text;"
      , "  if (rate_value < 8000 || rate_value > 384000) { pudu_host_fail(\"audio sample rate is outside 8000 through 384000\"); return (pudu_int){0}; }"
      , "  if (channels_value < 1 || channels_value > 8) { pudu_host_fail(\"audio channel count is outside 1 through 8\"); return (pudu_int){0}; }"
      , "  if (frames_value < 16 || frames_value > 4096) { pudu_host_fail(\"audio frames per buffer is outside 16 through 4096\"); return (pudu_int){0}; }"
      , "  if (buffers_value < 2 || buffers_value > 8) { pudu_host_fail(\"audio buffer count is outside 2 through 8\"); return (pudu_int){0}; }"
      , "  if (timeout_value < 1 || timeout_value > 60000) { pudu_host_fail(\"audio playback deadline is outside 1 through 60000 milliseconds\"); return (pudu_int){0}; }"
      , "  if (pcm.length == 0) { pudu_host_fail(\"audio clip is empty\"); return (pudu_int){0}; }"
      , "  if (pcm.length % ((size_t)channels_value * 2) != 0) { pudu_host_fail(\"audio PCM ends inside a frame\"); return (pudu_int){0}; }"
      , "#if defined(__APPLE__)"
      , "  uint64_t completed = 0;"
      , "  int32_t cancelled = 0;"
      , "  if (pudu_host_signal_requested()) pudu_audio_request_cancel(&cancelled);"
      , "  int status = pudu_audio_play((int32_t)rate_value, (int32_t)channels_value,"
      , "    pcm.bytes, pcm.length, (int32_t)frames_value, (int32_t)buffers_value,"
      , "    (int32_t)timeout_value, &cancelled, &completed);"
      , "  static const char *const words[] = {"
      , "    \"audio device playback failed in the platform adapter\","
      , "    \"audio device playback received an invalid argument\","
      , "    \"audio device playback deadline exceeded\","
      , "    \"audio output queue could not be created\","
      , "    \"audio output buffers could not be allocated\","
      , "    \"audio output buffer could not be enqueued\","
      , "    \"audio output queue could not start\","
      , "    \"audio output queue could not be released cleanly\","
      , "    \"audio output queue could not drain its final buffers\","
      , "    \"audio device playback was cancelled\""
      , "  };"
      , "  if (status == 0) pudu_host_done(0);"
      , "  else pudu_host_fail(words[status >= -9 && status <= -1 ? -status : 0]);"
      , "  return pudu_kernel_int((int64_t)completed);"
      , "#else"
      , "  pudu_host_fail(\"audio device playback is unsupported on this platform\");"
      , "  return (pudu_int){0};"
      , "#endif"
      , "}"
      ])
  , ("host_audio_stream_open", ["host_audio_stream_array"],
      [ "static pudu_box * pudu_host_audio_stream_open(pudu_int rate, pudu_int channels, pudu_int frames, pudu_int buffers) {"
      , "#if defined(__APPLE__)"
      , "  int64_t rate_value = pudu_kernel_signed(rate.bits);"
      , "  int64_t channels_value = pudu_kernel_signed(channels.bits);"
      , "  int64_t frames_value = pudu_kernel_signed(frames.bits);"
      , "  int64_t buffers_value = pudu_kernel_signed(buffers.bits);"
      , "  if (rate_value < 8000 || rate_value > 384000) { pudu_host_fail(\"audio stream sample rate is outside 8000 through 384000\"); return NULL; }"
      , "  if (channels_value < 1 || channels_value > 8) { pudu_host_fail(\"audio stream channel count is outside 1 through 8\"); return NULL; }"
      , "  if (frames_value < 16 || frames_value > 4096) { pudu_host_fail(\"audio stream frames per buffer is outside 16 through 4096\"); return NULL; }"
      , "  if (buffers_value < 2 || buffers_value > 8) { pudu_host_fail(\"audio stream buffer count is outside 2 through 8\"); return NULL; }"
      , "  static int cleanup_installed = 0;"
      , "  if (!cleanup_installed) {"
      , "    if (atexit(pudu_stream_teardown) != 0) pudu_memory_failure();"
      , "    cleanup_installed = 1;"
      , "  }"
      , "  if (pudu_stream_next == INT64_MAX) { pudu_host_fail(\"audio stream token space is exhausted\"); return NULL; }"
      , "  pudu_stream_entry *entry = malloc(sizeof *entry);"
      , "  if (entry == NULL) pudu_memory_failure();"
      , "  pudu_audio_stream *stream = NULL;"
      , "  int32_t actual_rate = 0, actual_channels = 0;"
      , "  int status = pudu_audio_stream_open((int32_t)rate_value, (int32_t)channels_value,"
      , "    (int32_t)frames_value, (int32_t)buffers_value, &stream, &actual_rate, &actual_channels);"
      , "  if (status != 0 || stream == NULL) {"
      , "    free(entry);"
      , "    if (status != 0) pudu_stream_problem(status);"
      , "    else pudu_host_fail(\"audio stream adapter returned no session\");"
      , "    return NULL;"
      , "  }"
      , "  *entry = (pudu_stream_entry){pudu_stream_next++, stream, pudu_streams};"
      , "  pudu_streams = entry;"
      , "  const uint64_t values[] = {(uint64_t)entry->token, (uint64_t)actual_rate, (uint64_t)actual_channels};"
      , "  return pudu_stream_answer(values, 3);"
      , "#else"
      , "  (void)rate; (void)channels; (void)frames; (void)buffers;"
      , "  pudu_host_fail(\"audio device streaming is unsupported on this platform\");"
      , "  return NULL;"
      , "#endif"
      , "}"
      ])
  , ("host_audio_stream_write", ["host_audio_stream_array"],
      [ "static pudu_box * pudu_host_audio_stream_write(pudu_int token, pudu_int rate, pudu_int channels, pudu_box * bytes, pudu_int timeout) {"
      , "#if defined(__APPLE__)"
      , "  int64_t rate_value = pudu_kernel_signed(rate.bits);"
      , "  int64_t channels_value = pudu_kernel_signed(channels.bits);"
      , "  int64_t timeout_value = pudu_kernel_signed(timeout.bits);"
      , "  pudu_text pcm = bytes->fields[0].text;"
      , "  if (rate_value < 8000 || rate_value > 384000) { pudu_host_fail(\"audio stream sample rate is outside 8000 through 384000\"); return NULL; }"
      , "  if (channels_value < 1 || channels_value > 8) { pudu_host_fail(\"audio stream channel count is outside 1 through 8\"); return NULL; }"
      , "  if (timeout_value < 1 || timeout_value > 60000) { pudu_host_fail(\"audio stream write deadline is outside 1 through 60000 milliseconds\"); return NULL; }"
      , "  if (pcm.length == 0) { pudu_host_fail(\"audio stream write is empty\"); return NULL; }"
      , "  if (pcm.length % ((size_t)channels_value * 2) != 0) { pudu_host_fail(\"audio stream PCM ends inside a frame\"); return NULL; }"
      , "  pudu_stream_entry **entry = pudu_stream_find(token);"
      , "  if (*entry == NULL) return NULL;"
      , "  uint64_t accepted = 0;"
      , "  int status = pudu_audio_stream_write((*entry)->stream, pcm.bytes, pcm.length, (int32_t)timeout_value, &accepted);"
      , "  const uint64_t values[] = {accepted, (uint64_t)(int64_t)status};"
      , "  return pudu_stream_answer(values, 2);"
      , "#else"
      , "  (void)token; (void)rate; (void)channels; (void)bytes; (void)timeout;"
      , "  pudu_host_fail(\"audio stream is closed or unknown\");"
      , "  return NULL;"
      , "#endif"
      , "}"
      ])
  , ("host_audio_stream_pause", ["host_audio_stream"],
      [ "static int pudu_host_audio_stream_pause(pudu_int token) {"
      , "#if defined(__APPLE__)"
      , "  pudu_stream_entry **entry = pudu_stream_find(token);"
      , "  if (*entry == NULL) return 0;"
      , "  return pudu_stream_problem(pudu_audio_stream_pause((*entry)->stream));"
      , "#else"
      , "  (void)token;"
      , "  pudu_host_fail(\"audio stream is closed or unknown\");"
      , "  return 0;"
      , "#endif"
      , "}"
      ])
  , ("host_audio_stream_resume", ["host_audio_stream"],
      [ "static int pudu_host_audio_stream_resume(pudu_int token) {"
      , "#if defined(__APPLE__)"
      , "  pudu_stream_entry **entry = pudu_stream_find(token);"
      , "  if (*entry == NULL) return 0;"
      , "  return pudu_stream_problem(pudu_audio_stream_resume((*entry)->stream));"
      , "#else"
      , "  (void)token;"
      , "  pudu_host_fail(\"audio stream is closed or unknown\");"
      , "  return 0;"
      , "#endif"
      , "}"
      ])
  , ("host_audio_stream_volume", ["host_audio_stream", "float_decode"],
      [ "static int pudu_host_audio_stream_volume(pudu_int token, uint64_t volume) {"
      , "#if defined(__APPLE__)"
      , "  double level = pudu_float_decode(volume);"
      , "  if (!(level >= 0.0 && level <= 1.0)) { pudu_host_fail(\"audio stream volume is outside 0 through 1\"); return 0; }"
      , "  pudu_stream_entry **entry = pudu_stream_find(token);"
      , "  if (*entry == NULL) return 0;"
      , "  return pudu_stream_problem(pudu_audio_stream_set_volume((*entry)->stream, level));"
      , "#else"
      , "  (void)token; (void)volume;"
      , "  pudu_host_fail(\"audio stream is closed or unknown\");"
      , "  return 0;"
      , "#endif"
      , "}"
      ])
  , ("host_audio_stream_snapshot", ["host_audio_stream_array"],
      [ "static pudu_box * pudu_host_audio_stream_snapshot(pudu_int token) {"
      , "#if defined(__APPLE__)"
      , "  pudu_stream_entry **entry = pudu_stream_find(token);"
      , "  if (*entry == NULL) return NULL;"
      , "  pudu_audio_stream_snapshot snapshot;"
      , "  int status = pudu_audio_stream_snapshot_read((*entry)->stream, &snapshot);"
      , "  if (status != 0) { pudu_stream_problem(status); return NULL; }"
      , "  const uint64_t values[] = {snapshot.submitted_frames, snapshot.acquired_frames,"
      , "    snapshot.clock_frames, snapshot.clock_nanoseconds, snapshot.underruns, snapshot.interruptions,"
      , "    snapshot.device_changes, snapshot.timeline_failures, (uint64_t)snapshot.state};"
      , "  return pudu_stream_answer(values, 9);"
      , "#else"
      , "  (void)token;"
      , "  pudu_host_fail(\"audio stream is closed or unknown\");"
      , "  return NULL;"
      , "#endif"
      , "}"
      ])
  , ("host_audio_stream_close", ["host_audio_stream"],
      [ "static int pudu_host_audio_stream_close(pudu_int token, int drain, pudu_int timeout) {"
      , "  int64_t timeout_value = pudu_kernel_signed(timeout.bits);"
      , "  if (timeout_value < 1 || timeout_value > 60000) { pudu_host_fail(\"audio stream close deadline is outside 1 through 60000 milliseconds\"); return 0; }"
      , "#if defined(__APPLE__)"
      , "  pudu_stream_entry **entry = pudu_stream_find(token);"
      , "  if (*entry == NULL) return 0;"
      , "  pudu_stream_entry *closed = *entry;"
      , "  *entry = closed->next;"
      , "  int status = pudu_audio_stream_close(closed->stream, drain, (int32_t)timeout_value);"
      , "  free(closed);"
      , "  return pudu_stream_problem(status);"
      , "#else"
      , "  (void)token; (void)drain;"
      , "  pudu_host_fail(\"audio stream is closed or unknown\");"
      , "  return 0;"
      , "#endif"
      , "}"
      ])
  ]
